<template>
  <main class="admin-login-page"><section class="admin-login-visual"><img src="/img/background_adminlogin.webp" alt="" /><div class="visual-shade"></div><div class="visual-copy"><p>KARINABEL OFFICE</p><h1>카리나벨의 하루를<br />세심하게 관리합니다.</h1><span>회원, 주문, 상품과 고객 문의를 한곳에서 확인하세요.</span></div></section><section class="admin-login-panel"><button type="button" class="home-link" @click="router.push('/')"><i class="fa-solid fa-arrow-left"></i> 홈페이지</button><div class="login-card"><img src="/img/logo2.png" alt="카리나벨" /><p class="login-eyebrow">SECURE ADMIN ACCESS</p><h2>관리자 로그인</h2><p class="login-intro">권한이 부여된 관리자 계정으로 로그인해 주세요.</p><form novalidate @submit.prevent="handleAdminLogin"><label><span>관리자 ID</span><div :class="['admin-input',{invalid:fieldError==='id'}]"><i class="fa-regular fa-user"></i><input v-model.trim="adminId" autocomplete="username" placeholder="관리자 ID" @input="clearError" /></div></label><label><span>비밀번호</span><div :class="['admin-input',{invalid:fieldError==='password'}]"><i class="fa-solid fa-lock"></i><input v-model="adminPassword" :type="showPassword?'text':'password'" autocomplete="current-password" placeholder="비밀번호" @input="clearError" /><button type="button" :aria-label="showPassword?'비밀번호 숨기기':'비밀번호 보기'" @click="showPassword=!showPassword"><i :class="showPassword?'fa-regular fa-eye-slash':'fa-regular fa-eye'"></i></button></div></label><p v-if="errorMessage" class="login-error" role="alert"><i class="fa-solid fa-circle-exclamation"></i>{{errorMessage}}</p><button class="login-submit" type="submit" :disabled="submitting"><i v-if="submitting" class="fa-solid fa-spinner fa-spin"></i>{{submitting?'확인 중...':'관리자 로그인'}}</button></form><div class="security-note"><i class="fa-solid fa-shield-halved"></i><p><strong>보안 안내</strong><span>공용 기기에서는 업무 후 반드시 로그아웃해 주세요.</span></p></div></div></section></main>
</template>
<script setup>
import{ref}from"vue";import{useRouter}from"vue-router";import AdminService from"@/api/AdminService";import store from"@/store";const router=useRouter(),adminId=ref(""),adminPassword=ref(""),showPassword=ref(false),submitting=ref(false),errorMessage=ref(""),fieldError=ref("");const clearError=()=>{errorMessage.value="";fieldError.value=""};const handleAdminLogin=async()=>{clearError();if(!adminId.value){fieldError.value="id";errorMessage.value="관리자 ID를 입력해 주세요.";return}if(!adminPassword.value){fieldError.value="password";errorMessage.value="비밀번호를 입력해 주세요.";return}submitting.value=true;try{const response=await AdminService.adminLogin({adminId:adminId.value,password:adminPassword.value});if(response.data?.role!=="admin"||!response.data?.token)throw new Error("관리자 권한을 확인할 수 없습니다.");await store.dispatch("login",response.data);await router.replace("/admin/dashboard")}catch(error){console.error(error);errorMessage.value=error.response?.data?.message||error.message||"관리자 ID 또는 비밀번호를 확인해 주세요."}finally{submitting.value=false}};
</script>
