nd:transparent;font-size:.76rem}.admin-input button{width:43px;height:100%;border:0;color:#94888e;background:transparent}.login-error{margin:-3px 0 13px;color:#a95d67;font-size:.65rem}.login-error i{margin-right:6px}.login-submit{width:100%;height:52px;display:flex;align-items:center;justify-content:center;gap:8px;border:0;color:#fff;background:#4f3a45;font-size:.77rem;font-weight:700}.login-submit:hover:not(:disabled){background:#413038;box-shadow:0 9px 22px rgba(64,43,53,.18);transform:translateY(-1px)}.security-note{display:flex;gap:10px;margin-top:27px;padding:14px;background:#f7f3f1;color:#a0737c}.security-note strong,.security-note span{display:block}.security-note strong{color:#675a60;font-size:.62rem}.security-note span{margin-top:1px;color:#9c9296;font-size:.54rem}@media(max-width:850px){.admin-login-page{grid-template-columns:1fr}.admin-login-visual{display:none}.admin-login-panel{min-height:100vh;padding:70px 20px 40px}}@media(max-width:480px){.login-card{padding:34px 22px}.home-link{top:20px;right:20px}}
